import{_ as r,o as a,c as o,a5 as t}from"./chunks/framework.B-qY3dMa.js";const u=JSON.parse('{"title":"Cursor 接入指南","description":"","frontmatter":{"title":"Cursor 接入指南","date":"2026-05-18T00:00:00.000Z","category":"拓展","tags":["Cursor","AI编程","接入教程","开发者"]},"headers":[],"relativePath":"connect/cursor.md","filePath":"connect/cursor.md","lastUpdated":1779073000000}'),s={name:"connect/cursor.md"};function d(n,e,c,h,i,l){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="cursor-接入指南" tabindex="-1">Cursor 接入指南 <a class="header-anchor" href="#cursor-接入指南" aria-label="Permalink to &quot;Cursor 接入指南&quot;">​</a></h1><p>AI 编程神器，通过自定义 API 接入熊猫Token平台，解锁更多模型。</p><p><strong>预计用时：5 分钟 · 推荐人群：开发者 · 支持平台：Win / Mac / Linux</strong></p><hr><h2 id="什么是-cursor" tabindex="-1">什么是 Cursor？ <a class="header-anchor" href="#什么是-cursor" aria-label="Permalink to &quot;什么是 Cursor？&quot;">​</a></h2><p>Cursor 是基于 VSCode 开发的 AI 代码编辑器，支持代码补全、自然语言生成代码、Agent 自动修改文件等功能。通过配置自定义 API Key + Base URL，可以接入熊猫Token平台的任意模型，降低使用成本。</p><div class="danger custom-block"><p class="custom-block-title">前提条件</p><p>Cursor 的自定义 API Keys（BYOK）功能需要 <strong>Cursor Pro 订阅</strong>才能使用，免费用户无法使用此功能。</p></div><hr><h2 id="step-01-下载安装-cursor" tabindex="-1">Step 01：下载安装 Cursor <a class="header-anchor" href="#step-01-下载安装-cursor" aria-label="Permalink to &quot;Step 01：下载安装 Cursor&quot;">​</a></h2><h3 id="_1-前往官网下载" tabindex="-1">1. 前往官网下载 <a class="header-anchor" href="#_1-前往官网下载" aria-label="Permalink to &quot;1. 前往官网下载&quot;">​</a></h3><p>访问 <a href="https://www.cursor.com" target="_blank" rel="noreferrer">cursor.com</a>，点击下载对应平台的安装包。</p><h3 id="_2-安装并注册账号" tabindex="-1">2. 安装并注册账号 <a class="header-anchor" href="#_2-安装并注册账号" aria-label="Permalink to &quot;2. 安装并注册账号&quot;">​</a></h3><p>安装完成后启动 Cursor，注册账号并登录。VSCode 用户可以一键导入所有配置和插件。</p><hr><h2 id="step-02-获取熊猫token-api-key" tabindex="-1">Step 02：获取熊猫Token API Key <a class="header-anchor" href="#step-02-获取熊猫token-api-key" aria-label="Permalink to &quot;Step 02：获取熊猫Token API Key&quot;">​</a></h2><h3 id="_1-登录平台并创建-key" tabindex="-1">1. 登录平台并创建 Key <a class="header-anchor" href="#_1-登录平台并创建-key" aria-label="Permalink to &quot;1. 登录平台并创建 Key&quot;">​</a></h3><p>访问 <a href="https://www.pandatoken.net" target="_blank" rel="noreferrer">www.pandatoken.net</a>，进入「控制台」→「令牌」，新建令牌并复制。</p><hr><h2 id="step-03-在-cursor-中配置自定义-api" tabindex="-1">Step 03：在 Cursor 中配置自定义 API <a class="header-anchor" href="#step-03-在-cursor-中配置自定义-api" aria-label="Permalink to &quot;Step 03：在 Cursor 中配置自定义 API&quot;">​</a></h2><h3 id="_1-打开-cursor-设置" tabindex="-1">1. 打开 Cursor 设置 <a class="header-anchor" href="#_1-打开-cursor-设置" aria-label="Permalink to &quot;1. 打开 Cursor 设置&quot;">​</a></h3><p>按 <code>Ctrl</code> + <code>Shift</code> + <code>J</code>（Windows/Linux）或 <code>Cmd</code> + <code>Shift</code> + <code>J</code>（macOS）打开 Cursor Settings，或点击右上角齿轮图标。</p><h3 id="_2-进入-models-页面" tabindex="-1">2. 进入 Models 页面 <a class="header-anchor" href="#_2-进入-models-页面" aria-label="Permalink to &quot;2. 进入 Models 页面&quot;">​</a></h3><p>在 Cursor Settings 中找到「Models」选项卡，下滑找到 <strong>OpenAI API Key</strong> 和 <strong>Override OpenAI Base URL</strong> 两个输入框。</p><h3 id="_3-填写配置信息" tabindex="-1">3. 填写配置信息 <a class="header-anchor" href="#_3-填写配置信息" aria-label="Permalink to &quot;3. 填写配置信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置项</th><th>填写内容</th></tr></thead><tbody><tr><td>OpenAI API Key</td><td>你从熊猫Token平台复制的令牌</td></tr><tr><td>Override OpenAI Base URL</td><td><code>https://www.pandatoken.net/v1</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">注意</p><p>填完 API Key 后需要按回车确认，然后再填 Override Base URL。</p></div><h3 id="_4-添加自定义模型" tabindex="-1">4. 添加自定义模型 <a class="header-anchor" href="#_4-添加自定义模型" aria-label="Permalink to &quot;4. 添加自定义模型&quot;">​</a></h3><p>点击「Add custom model」，输入你想使用的模型名称，例如 <code>deepseek-v3</code>、<code>deepseek-r1</code>、<code>gpt-4o</code> 等，然后在模型列表中勾选启用。</p><h3 id="_5-在-chat-中使用" tabindex="-1">5. 在 Chat 中使用 <a class="header-anchor" href="#_5-在-chat-中使用" aria-label="Permalink to &quot;5. 在 Chat 中使用&quot;">​</a></h3><p>按 <code>Ctrl</code> + <code>L</code> 打开 Chat 面板，在模型选择器中选择你刚刚添加的模型，即可开始 AI 辅助编程。</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Tab 补全还是用的 Cursor 原来的模型</strong></p><p>自定义 API Key 只影响 Chat 和 Composer 功能，Tab 自动补全仍然使用 Cursor 内置模型，这是 Cursor 的限制，无法更改。</p><p><strong>提示连接失败</strong></p><p>请确认 Base URL 填写为 <code>https://www.pandatoken.net/v1</code>，末尾不要加 <code>/chat/completions</code>，Cursor 会自动拼接。</p><hr><p>配置完成！Cursor 已成功接入熊猫Token平台，开启 AI 辅助编程新体验。</p>',38)])])}const b=r(s,[["render",d]]);export{u as __pageData,b as default};
